import * as THREE from './three.module.mjs';
export function buildBoostWorld(world,pickups=[],pads=[]){
 const markers=[],padMarkers=[];const core=new THREE.MeshStandardMaterial({color:0x36dfff,emissive:0x12a6d9,emissiveIntensity:1.2,roughness:.3}),white=new THREE.MeshBasicMaterial({color:0xeaffff,toneMapped:false}),pad=new THREE.MeshBasicMaterial({color:0x4bddff,transparent:true,opacity:.6,depthWrite:false});
 for(const p of pickups){const group=new THREE.Group();group.name='Shared boost refill '+(p.id+1);group.position.set(p.x,p.y,p.z);world.add(group);
  const base=new THREE.Mesh(new THREE.RingGeometry(.9,1.2,24),pad.clone());base.rotation.x=-Math.PI/2;base.position.y=.07;group.add(base);
  const item=new THREE.Group();item.position.y=1.7;group.add(item);const diamond=new THREE.Mesh(new THREE.OctahedronGeometry(.85),core);item.add(diamond);
  const bolt=new THREE.Shape();bolt.moveTo(.08,.68);bolt.lineTo(-.4,-.08);bolt.lineTo(-.06,-.08);bolt.lineTo(-.18,-.65);bolt.lineTo(.42,.16);bolt.lineTo(.08,.16);bolt.closePath();const icon=new THREE.Mesh(new THREE.ShapeGeometry(bolt),white);icon.position.z=.87;item.add(icon);
  markers.push({group,item,base,icon,id:p.id});
 }
 for(const p of pads){const group=new THREE.Group();group.name='Reusable boost pad '+(p.id+1);group.position.set(p.x,p.y+.05,p.z);world.add(group);const ring=new THREE.Mesh(new THREE.RingGeometry(1.45,2.05,24),pad.clone());ring.rotation.x=-Math.PI/2;group.add(ring);const arrow=new THREE.Mesh(new THREE.ConeGeometry(.62,1.4,4),white);arrow.rotation.x=Math.PI/2;arrow.position.y=.08;arrow.rotation.z=p.heading||0;group.add(arrow);padMarkers.push({group,ring,arrow,id:p.id})}
 return{update(run,time,camera){for(const m of markers){const p=run.boostPickups[m.id],ready=p.readyAt<=run.time;m.item.visible=ready;m.base.material.opacity=ready?.6:.12;m.item.position.y=1.7+Math.sin(time*3+m.id)*.15;m.item.quaternion.copy(camera.quaternion);m.icon.scale.setScalar(1+.07*Math.sin(time*4))}for(const m of padMarkers){m.group.position.y=run.boostPads[m.id].y+.05+Math.sin(time*5+m.id)*.025;m.ring.material.opacity=.42+.18*Math.sin(time*4+m.id);m.arrow.rotation.y=time*1.5+m.id}},dispose(){for(const m of markers){m.group.traverse(o=>o.geometry?.dispose());m.base.material.dispose();m.group.removeFromParent()}for(const m of padMarkers){m.group.traverse(o=>o.geometry?.dispose());m.ring.material.dispose();m.group.removeFromParent()}core.dispose();white.dispose();pad.dispose()}};
}
export function drawBoostMarkers(ctx,xy,run,large=false){
 for(const p of run.boostPickups){const ready=p.readyAt<=run.time,[x,y]=xy(p.x,p.z),r=large?8:4;ctx.save();ctx.globalAlpha=ready?1:.35;ctx.fillStyle=ready?'#37ddff':'#577e89';ctx.strokeStyle='#103545';ctx.lineWidth=1.4;ctx.beginPath();ctx.moveTo(x,y-r);ctx.lineTo(x+r,y);ctx.lineTo(x,y+r);ctx.lineTo(x-r,y);ctx.closePath();ctx.fill();ctx.stroke();if(large){ctx.fillStyle='#102e3c';ctx.font='bold 13px Arial';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('ϟ',x,y)}ctx.restore()}
 for(const p of run.boostPads||[]){const[x,y]=xy(p.x,p.z),r=large?9:4.8;ctx.save();ctx.fillStyle='#4bddff';ctx.strokeStyle='#103545';ctx.lineWidth=1.2;ctx.globalAlpha=.78;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#102e3c';ctx.font='bold '+(large?'13':'8')+'px Arial';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('↗',x,y);ctx.restore()}
}
